        const _sendAjaxVanilla = function ( url, stringifiedData, type ) {
            return new Promise(function (resolve, reject) {
                let request = new XMLHttpRequest();
                request.open( type, url );
                request.setRequestHeader( 'Content-Type', 'application/json; charset=UTF-8;' );
                request.onload = function () {
                    if ( request.status < 300 ) {
                        //BaseUtils.logMessage( BaseUtils.LogLevelType["DEBUG"], "Got the response", request, request.response );
                        resolve( JSON.parse(request.response) );
                    }
                    else {
                        BaseUtils.logMessage( BaseUtils.LogLevelType["WARN"], 'Got status ' + request.status + " when sending data to url '" + url + "' with data", stringifiedData );
                        reject( new Error( request.statusText ) );
                    }
                };

                request.onerror = function () {
                    reject( new Error( I18nTranslator.i18n( 'exceptions.networkError' ) ) );
                };

                if ( type !== 'get' && type !== 'delete' && stringifiedData !== null && stringifiedData !== undefined ) {
                    //BaseUtils.logMessage( BaseUtils.LogLevelType["DEBUG"], "Will send " + type + " request to url '" + url + "'. Data is ", stringifiedData );
                    request.send( stringifiedData );
                }
                else if ( type === 'delete' && BaseUtils.isDefined( stringifiedData ) ) {
                    request.send( stringifiedData );
                }
                else {
                    //BaseUtils.logMessage( BaseUtils.LogLevelType["DEBUG"], "Will send " + type + " request to url '" + url + "'. Data is empty" );
                    request.send();
                }
            })
        };
